select x.record->'content_body'->>'resource_id' as resource_id,e.content_id,
not exists(select 1 from jsonb_each(x.record) f where to_jsonb(e)->f.key is distinct from to_jsonb(jsonb_populate_record(null::public.explore_content,x.record))->f.key) as matches
from expected x left join public.explore_content e on e.content_id::text=x.record->>'content_id' or e.content_body->>'resource_id'=x.record->'content_body'->>'resource_id')
select resource_id,count(content_id) as record_count,case when count(content_id)=1 and bool_and(matches) then 'PASS' else 'CHECK MISSING, DUPLICATE, OR CHANGED FIELDS' end as qa_result from checked group by resource_id order by resource_id;
